head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil00049";
scwin.formObj = undefined;
scwin.rtnVal = "";
scwin.chkArrNo = undefined;
scwin.chkTitle = undefined;
scwin.obj = undefined;
scwin.frameId = undefined;
scwin.frame = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "iframe_11", attr: "src", fn: function () { return "/submission/searchDisclosureDocument.do?method=srchBondListCorpIsuList&tgtIsurCd=" + String((dma_pageContext.get("tgtIsurCd") ?? "")) + "&pageSize=10"; } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.formObj = (document.popForm || { elements: [] });
        const openerOjb = scwin.frame.document.comFrm;
        $c.util.getComponent("ipt_formKey").setValue(openerOjb.formKey.value);
        $c.util.getComponent("ipt_returnKey").setValue(openerOjb.returnKey.value);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00049.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.chkArrNo =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00049' }); }

try { scwin.chkTitle =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00049' }); }

try { scwin.obj =opener.Potential.Provider; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00049' }); }

try { scwin.frameId =scwin.obj.ActiveFrame.FrameID; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00049' }); }

try { scwin.frame =scwin.obj.Provider(scwin.frameId).ActiveFrame; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00049' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_attrReals();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil00049.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_selectedAll_onclick
 * @description btn_selectedAll 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_selectedAll_onclick = async function(e){
    try {
        await scwin.selectedAll()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00049.btn_selectedAll_onclick' }); }
};

/**
 * @method
 * @name btn_selected_onclick
 * @description btn_selected 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_selected_onclick = async function(e){
    try {
        await scwin.selected()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00049.btn_selected_onclick' }); }
};

/**
 * @method
 * @name btn_close_onclick
 * @description btn_close 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_close_onclick = function(e){
    try {
        scwin.close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00049.btn_close_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_selectedAll
 * @description selected All 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_selectedAll = async function () {
    const sbmOptions = {
        id: "tx_fn_selectedAll",
        method: "post",
        action: "/submission/ajaxGetListData.do?method=ajaxGetBondListCorpIsuList",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkIt
 * @description check It 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.checkIt = function (ver) {
    const subObj = document.iframe.searchForm.bndIsuInfo;
    let tmpVal = null;
    let arrLength = 0;
    const arrNo = ((ver.value).split("|"))[0];
    scwin.resetRtnVal(arrNo);
    if (scwin.chkArrNo.length !== 0) {
        arrLength = scwin.chkArrNo.length;
    }
    if (ver.checked === true) {
        tmpVal = (ver.value).split("|");
        scwin.chkArrNo[arrLength] = tmpVal[0];
        scwin.chkTitle[arrLength] = tmpVal[1];
    }
    scwin.rtnVal = scwin.chkArrNo.join(",") + "|" + scwin.chkArrNo.join("\n");
    $c.util.getComponent("txt_docs").setValue(scwin.chkTitle.join(", "));
};

/**
 * @method
 * @name resetRtnVal
 * @description reset Rtn Val 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.resetRtnVal = function (ver) {
    const tmpArr1 = [];
    const tmpArr2 = [];
    let cnt = 0;
    for (let i = 0; i < scwin.chkArrNo.length; i++) {
        if (scwin.chkArrNo[i] !== ver) {
            tmpArr1[cnt] = scwin.chkArrNo[i];
            tmpArr2[cnt] = scwin.chkTitle[i];
            cnt++;
        }
    }
    scwin.chkArrNo = [];
    scwin.chkTitle = [];
    scwin.chkArrNo = tmpArr1;
    scwin.chkTitle = tmpArr2;
};

/**
 * @method
 * @name selected
 * @description selected 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selected = async function () {
    scwin.formObj = (document.popForm || { elements: [] });
    let isChoice = false;
    const subObj = document.iframe.searchForm.bndIsuInfo;
    if (scwin.chkArrNo.length !== 0) {
        isChoice = true;
    }
    if (isChoice) {
        scwin.frame.fn_setSelectedData($c.util.getComponent("ipt_formKey").getValue(), $c.util.getComponent("ipt_keyValue").getValue(), decodeURIComponent($c.util.getComponent("ipt_returnKey").getValue()), scwin.chkArrNo.join(","), scwin.chkTitle.join(",\n"));
        $c.win.closePopup();
    } else {
        await $c.win.alert("종목을 하나 이상 선택하세요!");
    }
};

/**
 * @method
 * @name setCheckedCheckBox
 * @description set Checked Check Box 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.setCheckedCheckBox = function (ver) {
    const subObj = document.iframe.searchForm.bndIsuInfo;
    let tmpVal = null;
    if (ver !== 0) {
        if (scwin.chkArrNo.length !== 0) {
            for (let i = 0; i < scwin.chkArrNo.length; i++) {
                for (let k = 0; k < subObj.bndIsuInfo.length; k++) {
                    tmpVal = (subObj.bndIsuInfo[k].value).split("|");
                    if (scwin.chkArrNo[i] === tmpVal[0]) {
                        subObj.bndIsuInfo[k].checked = true;
                    }
                }
            }
        }
    }
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    $c.win.closePopup();
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name selectedAllDone
 * @description selected All Done 처리
 * @param {*} data 데이터
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectedAllDone = async function (data) {
    await $c.win.alert('대상종목으로 ' + data.arrCount + '건이 선택되었습니다.');
    $c.util.getComponent("txt_docs").setValue(data.isuCodeNmArr);
    scwin.frame.fn_setSelectedData($c.util.getComponent("ipt_formKey").getValue(), $c.util.getComponent("ipt_keyValue").getValue(), decodeURIComponent($c.util.getComponent("ipt_returnKey").getValue()), data.isuCodeArr, data.isuCodeNmArr);
    $c.win.closePopup();
};

/**
 * @method
 * @name selectedAll
 * @description selected All 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectedAll = async function () {
    const r = await scwin.tx_fn_selectedAll();
    try {
        scwin.selectedAllDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldfil00049.fn_selectedAll' });
    }
    return r;
};
